from lib import *
S = SS('f134')
R = J('f134'); bf = R['buf']
steps = [
    step("真实的 nginx(自签证书)终止 TLS,后面是 gunicorn(http)。gunicorn 不信任任何代理地址(--forwarded-allow-ips 设成别的)、Flask 也没有 ProxyFix 时,浏览器访问的是 https://localhost:端口/info,Flask 看到的是 scheme = http、is_secure = False,url_for(_external=True) 生成 http://localhost:端口/info;规则是 /dir/ 时访问 /dir 得到的 308 重定向 Location 也是 http://…/dir/——用户被从 https 重定向到了 http。", t=tl(S(1)), mark=lidx(S(1), '/info', 'GET /dir'), kv=KV([['Flask 看到', 'http,is_secure=False'], ['重定向', 'Location 变成 http://']], ['重定向'])),
    step("gunicorn 用默认设置时:它默认信任来自 127.0.0.1 的 X-Forwarded-Proto,自己把它翻译成 wsgi.url_scheme,所以同样的 nginx 配置下,Flask 没有 ProxyFix 也看到 scheme = https、is_secure = True,url_for 与 308 的 Location 都是 https。看起来「自动好了」——但这取决于 gunicorn 的默认信任范围(只对 X-Forwarded-Proto 有效,X-Forwarded-For 与 Host 它不处理)。", t=tl(S(2)), done=lidx(S(2), '/info', 'GET /dir', 'gunicorn 自己'), kv=KV([['gunicorn 默认', '信任 127.0.0.1 的 X-Forwarded-Proto'], ['只管 proto', '不管 X-Forwarded-For 与 Host']], ['gunicorn 默认'])),
    step("gunicorn 不信任代理,由 Flask 的 ProxyFix(x_for=1, x_proto=1, x_host=1) 负责:nginx 配 proxy_set_header Host $http_host、X-Forwarded-For $remote_addr、X-Forwarded-Proto $scheme;Flask 看到 scheme = https、is_secure = True、host = localhost:端口(Host 用 $http_host 才保留端口,写成 $host 会丢端口),外部链接与重定向都是 https。这样不依赖 gunicorn 的默认行为,三个头都由应用显式声明信任几层代理。", t=tl(S(3)), done=lidx(S(3), '/info', 'GET /dir'), kv=KV([['nginx 设头', 'Host / X-Forwarded-For / X-Forwarded-Proto'], ['ProxyFix', 'x_for / x_proto / x_host 各信任 1 层'], ['Host', '用 $http_host 保留端口']], ['ProxyFix'])),
    step("HTTP 到 HTTPS 的跳转由 nginx 做:访问 http 端口的 /info?x=1 得到 301,Location 是 https://127.0.0.1:端口/info?x=1(路径与查询串保留)。这个跳转发生在 Flask 之前,Flask 不会看到那个 http 请求。", t=tl(S(4)), done=lidx(S(4), '301'), kv=KV([['nginx return 301', '在到达 Flask 之前跳转']], ['nginx return 301'])),
    step("nginx 在 Flask 之前的限制:client_max_body_size 默认 1m,上传 500 KB 与 900 KB → 200;1100 KB 与 3000 KB → 413,是 nginx 直接拒绝的,请求没有到达 Flask(所以 Flask 的 MAX_CONTENT_LENGTH 不会生效);把 client_max_body_size 改成 5m 后 3000 KB → 200。上传限制要在 nginx 与 Flask 两处配套。", t=tl(S(5)), done=lidx(S(5), '500 KB', '900 KB', '5m'), mark=lidx(S(5), '1100 KB', '3000 KB →'), kv=KV([['client_max_body_size', '默认 1m,超过由 nginx 返回 413'], ['MAX_CONTENT_LENGTH', 'nginx 放行后才轮到它']], ['client_max_body_size'])),
    step(f"反向代理的缓冲会让流式响应失效:一个每 0.3 秒吐一块、共 5 块的响应。proxy_buffering on(默认)时,客户端在约 {bf['on'][0]} ms 才一次性收到全部(5 块的到达时间相同);proxy_buffering off 时,第一块 {bf['off'][0]} ms 到达,之后每 0.3 秒一块,最后一块 {bf['off'][1]} ms。第 118 篇的流式 JSON、第 149 篇的 SSE 经过 nginx 时都要关缓冲(或在响应里用 X-Accel-Buffering: no,这一项本篇没有验证)。", b=bars([['buffering on 首块', bf['on'][0], f"{bf['on'][0]} ms"], ['buffering off 首块', bf['off'][0], f"{bf['off'][0]} ms"]], bf['on'][0], mark=[0], done=[1]), t=tl(S(6)), mark=lidx(S(6), 'proxy_buffering on'), done=lidx(S(6), 'proxy_buffering off'), kv=KV([['on', f"全部在 {bf['on'][0]} ms 一次性到"], ['off', f"首块 {bf['off'][0]} ms,逐块到达"]], ['off'])),
]
A = mkartf('f134', 134, 'Flask,HTTPS,nginx,反向代理,ProxyFix,真实验证,动画演示',
    '用真实的 nginx(自签证书终止 TLS)加 gunicorn 实测 HTTPS 与反向代理:Flask 看不到 https 时外部链接与重定向变成 http;gunicorn 默认只翻译 X-Forwarded-Proto;ProxyFix 与 nginx 的 X-Forwarded-* 配套;Host 要用 $http_host;nginx 的 client_max_body_size 先于 Flask 返回 413;proxy_buffering 让流式响应一次性到达。',
    'HTTPS 在 nginx 终止之后,Flask 怎么知道用户走的是 https?重定向和外部链接会不会变成 http?上传限制和流式响应经过 nginx 会怎样?这篇起一个真的 nginx 与 gunicorn,把每种配置的结果量出来。',
    [('http → https', '没有处理代理头时,308 重定向的 Location 变成 http 的方向'), ('413', 'nginx 在请求到达 Flask 之前拒绝超过 client_max_body_size 的上传'), (f'{bf["on"][0]} → {bf["off"][0]} ms', 'proxy_buffering on 与 off 时流式响应第一块到达的时间')],
    [('Flask 看到的是 http', '<p>上一篇:<a href="flask-security-headers.html">安全响应头</a>;下一篇:<a href="flask-trusted-proxy-headers.html">信任代理头配置</a>。</p><p>nginx 是自己用 brew 装的,用自己的配置文件跑在非默认端口,证书是临时生成的自签证书(请求时关闭证书校验)。</p>'), ('gunicorn 的默认行为', None), ('ProxyFix 显式信任', None), ('http 跳转 https', None), ('nginx 先于 Flask 的限制', None), ('代理缓冲与流式响应', None)],
    steps, [ENV_F + '。nginx 1.31.6(自己的配置、非默认端口)、gunicorn、自签证书', '没有验证:Let\'s Encrypt 等真实证书的签发与续期、HTTP/2 与 HTTP/3、TLS 版本与密码套件配置、WebSocket 的升级头配置(见第 150 篇)、X-Accel-Buffering 头、proxy_read_timeout 对慢请求的 504'], 'HTTPS 与反向代理')
